#include <string>
#include <unordered_set>
using namespace std;

class Solution {
public:
    bool halvesAreAlike(string s) {
        unordered_set<char> vowels = {'a','e','i','o','u','A','E','I','O','U'};
        int mid = s.size() / 2;
        int diff = 0;
        for (int i = 0; i < mid; ++i) {
            if (vowels.count(s[i])) diff++;
            if (vowels.count(s[mid + i])) diff--;
        }
        return diff == 0;
    }
};

class Solution {
    public boolean halvesAreAlike(String s) {
        String vowels = "aeiouAEIOU";
        int mid = s.length() / 2;
        int diff = 0;
        for (int i = 0; i < mid; ++i) {
            if (vowels.indexOf(s.charAt(i)) >= 0) diff++;
            if (vowels.indexOf(s.charAt(mid + i)) >= 0) diff--;
        }
        return diff == 0;
    }
}

