var halvesAreAlike = function(s) {
    const vowels = new Set(['a','e','i','o','u','A','E','I','O','U']);
    const mid = s.length / 2;
    let diff = 0;
    for (let i = 0; i < mid; ++i) {
        if (vowels.has(s[i])) diff++;
        if (vowels.has(s[mid + i])) diff--;
    }
    return diff === 0;
};
